  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Compute the final booking price after applying reward-based discount rules.
   * Algorithm:
   * 1. If customer, bookingTime, or trip price is invalid or missing, return this trip's original price.
   * 2. Obtain the customer's membership package.
   * 3. If the package does not contain Award.DISCOUNTS, return the original price.
   * 4. Check whether bookingTime is at least 24 hours before departure.
   * 5. If the 24-hour condition is not satisfied, return the original price.
   * 6. Apply a 20 percent discount: finalPrice = price * 0.8.
   * 7. Round the result to one decimal place and return it.
   * Related Features:
   * - price
   * - departureDate
   * - departureTime
   * - driver
   * - bookings
   * Related Classes: Trip, Customer, MembershipPackage, Award
   * Input:
   * - customer: Customer; the customer making the booking.
   * - bookingTime: String; time the booking is made, in a parseable date-time format.
   * Output:
   * - double; discounted price rounded to one decimal place, or the original trip price if discount conditions are not satisfied.
   * Pre-condition:
   * - Trip price is defined.
   * - Customer and bookingTime may be validated before discount computation.
   * - Time comparison between bookingTime and trip departure is supported.
   * Post-condition:
   * - No persistent state is modified.
   * - Returned value reflects discount rules only.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
    {
      return getPrice();
    }

    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return getPrice();
    }

    if (getDepartureDate() == null || getDepartureTime() == null)
    {
      return getPrice();
    }

    try
    {
      SimpleDateFormat formatter = new SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.ENGLISH);
      Date bookingDateTime = formatter.parse(bookingTime);
      Date departureDateTime = formatter.parse(formatter.format(getDepartureDate()) + " " + getDepartureTime());
      long diffMillis = departureDateTime.getTime() - bookingDateTime.getTime();
      if (diffMillis < 24L * 60L * 60L * 1000L)
      {
        return getPrice();
      }
    }
    catch (ParseException e)
    {
      return getPrice();
    }

    double finalPrice = getPrice() * 0.8d;
    return Math.round(finalPrice * 10.0d) / 10.0d;
    
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Compute points earned on this trip for a given customer in the requested month.
   * Algorithm:
   * 1. If customer or currentMonth is null, return 0.
   * 2. Verify the customer has a membership package with Award.POINTS.
   * 3. If not eligible, return 0.
   * 4. For each booking in this trip’s bookings:
   *    - If the booking belongs to the input customer and booking.isInMonth(currentMonth) is true, add booking.numberOfSeats * 5.
   * 5. Return the total points.
   * Related Features:
   * - bookings
   * - numberOfSeats
   * - departureDate
   * Related Classes: Trip, Booking, Customer, MembershipPackage, Award
   * Input:
   * - customer: Customer; customer whose points are being computed.
   * - currentMonth: String; target month, in the supported month format.
   * Output:
   * - int; total points, where each qualifying booked seat yields 5 points.
   * Pre-condition:
   * - Trip and customer exist.
   * - The trip’s bookings list is accessible.
   * - The customer’s membership package can be checked.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
    {
      return 0;
    }

    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.POINTS))
    {
      return 0;
    }

    int totalPoints = 0;
    if (getBookings() != null)
    {
      for (Booking booking : getBookings())
      {
        if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
        {
          totalPoints += booking.getNumberOfSeats() * 5;
        }
      }
    }
    return totalPoints;
    
  }

